// Package notices is the third-party notice data embedded in mtm: for every
// module the binary links (and the Go standard library), its licence and
// notice files, each with the SPDX identifiers found in its text. The data
// is generated by ./gen (make licenses) from `go list -deps` and the module
// cache; a test fails on a licence this package cannot name, on a licence
// outside Allowed, and on data older than go.mod (Check).
package notices

import (
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"regexp"
	"slices"
	"sort"
	"strings"
)

//go:embed data
var dataFS embed.FS

// Unknown is the identifier of a licence file whose text matches no known licence.
const Unknown = "unknown"

// Kinds of file.
const (
	KindLicense = "license" // a licence: it names the terms the code is under
	KindNotice  = "notice"  // an attribution or notice file
)

// Allowed are the licences mtm may link or copy. Adding one is a reviewed edit.
var Allowed = []string{"Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC", "MIT", "MPL-2.0", "OFL-1.1", "Public-Domain"}

// Reviewed are licence-named files that name no licence, each looked at and
// kept as a notice, with why. Key: "module/path file". Adding a row is a
// reviewed edit; a new unknown licence file still fails the check.
var Reviewed = map[string]string{
	"modernc.org/memory LICENSE-LOGO": "one line, the URL of the logo image on Wikimedia Commons; no code is covered",
}

// File is one licence or notice file of a module.
type File struct {
	Name string   `json:"name"`           // path inside the module
	Kind string   `json:"kind"`           // KindLicense or KindNotice
	SPDX []string `json:"spdx,omitempty"` // licences found in the text; [Unknown] when a licence file matches none
	Text string   `json:"text"`           // hash of the text (Text)
}

// Module is one module the binary links.
type Module struct {
	Path       string `json:"path"`
	Version    string `json:"version,omitempty"`
	Main       bool   `json:"main,omitempty"`       // the main module (matomeru)
	Std        bool   `json:"std,omitempty"`        // the Go standard library
	DaemonOnly bool   `json:"daemonOnly,omitempty"` // linked only when the daemon is built in
	Files      []File `json:"files"`
}

// Licenses is the module's SPDX identifiers from its licence files, sorted.
func (m Module) Licenses() []string {
	var out []string
	for _, f := range m.Files {
		if f.Kind != KindLicense {
			continue
		}
		for _, s := range f.SPDX {
			if !slices.Contains(out, s) {
				out = append(out, s)
			}
		}
	}
	sort.Strings(out)
	return out
}

// Index is the generated file.
type Index struct {
	Modules  []Module `json:"modules"`
	Unlinked []Module `json:"unlinked,omitempty"` // go.mod requirements no build links; Files empty
}

// Load reads the embedded data.
func Load() (Index, error) {
	b, err := dataFS.ReadFile("data/notices.json")
	if err != nil {
		return Index{}, err
	}
	var ix Index
	return ix, json.Unmarshal(b, &ix)
}

// Text is the licence text with hash h from the embedded data.
func Text(h string) (string, error) {
	b, err := dataFS.ReadFile("data/texts/" + h + ".txt")
	return string(b), err
}

// Linked is the modules of a build: all of them with the daemon, without
// DaemonOnly ones when it is left out (-tags nodaemon).
func (ix Index) Linked(daemon bool) []Module {
	var out []Module
	for _, m := range ix.Modules {
		if m.DaemonOnly && !daemon {
			continue
		}
		out = append(out, m)
	}
	return out
}

// Hash names a licence text.
func Hash(text string) string {
	s := sha256.Sum256([]byte(text))
	return hex.EncodeToString(s[:])[:16]
}

type rule struct {
	spdx string
	all  []string // every phrase must appear (normalised, lower case)
	none []string // none may appear
}

// The order is the order SPDX identifiers are reported in. BSD-2 and BSD-3
// share their first two clauses; the third (no endorsement) tells them apart.
var rules = []rule{
	{"Apache-2.0", []string{"apache license", "version 2.0, january 2004"}, nil},
	{"MPL-2.0", []string{"mozilla public license version 2.0"}, nil},
	{"OFL-1.1", []string{"sil open font license", "version 1.1"}, nil},
	{"MIT", []string{"permission is hereby granted, free of charge, to any person obtaining a copy", "the software is provided \"as is\""}, nil},
	{"ISC", []string{"permission to use, copy, modify, and/or distribute this software for any purpose with or without fee"}, nil},
	{"Public-Domain", []string{"dedicated to the public domain"}, nil},
	{"BSD-3-Clause", []string{"redistribution and use in source and binary forms", "neither the name"}, nil},
	{"BSD-3-Clause", []string{"redistribution and use in source and binary forms", "endorse or promote"}, nil},
	{"BSD-2-Clause", []string{"redistribution and use in source and binary forms", "this software is provided by the copyright holders"}, []string{"neither the name", "endorse or promote"}},
}

var space = regexp.MustCompile(`\s+`)

func normalise(s string) string {
	s = strings.NewReplacer("“", "\"", "”", "\"", "’", "'", "*", " ", "//", " ", "#", " ").Replace(s)
	return strings.ToLower(space.ReplaceAllString(s, " "))
}

// Classify names the licences whose text appears in text, in rule order.
// None found is nil.
func Classify(text string) []string {
	n := normalise(text)
	var out []string
	for _, r := range rules {
		ok := true
		for _, p := range r.all {
			ok = ok && strings.Contains(n, p)
		}
		for _, p := range r.none {
			ok = ok && !strings.Contains(n, p)
		}
		if ok && !slices.Contains(out, r.spdx) {
			out = append(out, r.spdx)
		}
	}
	return out
}

// Check is the notices check. modRequires are go.mod's required modules
// (path to version). It reports every problem: a licence file of unknown or
// disallowed licence, a linked module with no licence file, a text missing
// from the data, a go.mod module absent from the data or at another version
// (stale data), and a data module go.mod no longer requires.
func (ix Index) Check(modRequires map[string]string, text func(hash string) (string, error)) []string {
	var bad []string
	seen := map[string]bool{}
	for _, m := range ix.Modules {
		seen[m.Path] = true
		licensed := false
		for _, f := range m.Files {
			t, err := text(f.Text)
			switch {
			case err != nil:
				bad = append(bad, fmt.Sprintf("%s: %s: text %s missing", m.Path, f.Name, f.Text))
			case Hash(t) != f.Text:
				bad = append(bad, fmt.Sprintf("%s: %s: text does not match its hash", m.Path, f.Name))
			}
			if f.Kind != KindLicense {
				continue
			}
			licensed = true
			if len(f.SPDX) == 0 || slices.Contains(f.SPDX, Unknown) {
				bad = append(bad, fmt.Sprintf("%s: %s: unknown licence", m.Path, f.Name))
			}
			for _, s := range f.SPDX {
				if s != Unknown && !slices.Contains(Allowed, s) {
					bad = append(bad, fmt.Sprintf("%s: %s: licence %s is not allowed", m.Path, f.Name, s))
				}
			}
		}
		if !licensed {
			bad = append(bad, fmt.Sprintf("%s: no licence file", m.Path))
		}
		if m.Main || m.Std {
			continue
		}
		if want, ok := modRequires[m.Path]; !ok {
			bad = append(bad, fmt.Sprintf("%s: in the notices but not in go.mod (stale: run make licenses)", m.Path))
		} else if want != m.Version {
			bad = append(bad, fmt.Sprintf("%s: notices have %s, go.mod %s (stale: run make licenses)", m.Path, m.Version, want))
		}
	}
	for _, m := range ix.Unlinked {
		seen[m.Path] = true
		if want, ok := modRequires[m.Path]; !ok || want != m.Version {
			bad = append(bad, fmt.Sprintf("%s: unlinked entry out of date (stale: run make licenses)", m.Path))
		}
	}
	for p := range modRequires {
		if !seen[p] {
			bad = append(bad, fmt.Sprintf("%s: in go.mod but not in the notices (stale: run make licenses)", p))
		}
	}
	sort.Strings(bad)
	return bad
}

// ParseRequires is the module requirements of a go.mod file (path to
// version), direct and indirect. Replace, exclude and retract lines are not
// requirements.
func ParseRequires(gomod string) map[string]string {
	out := map[string]string{}
	block := ""
	for _, line := range strings.Split(gomod, "\n") {
		line = strings.TrimSpace(line)
		if i := strings.Index(line, "//"); i >= 0 {
			line = strings.TrimSpace(line[:i])
		}
		switch {
		case line == ")":
			block = ""
			continue
		case strings.HasSuffix(line, "("):
			block = strings.TrimSpace(strings.TrimSuffix(line, "("))
			continue
		case line == "":
			continue
		}
		f := strings.Fields(line)
		if block == "require" && len(f) == 2 {
			out[f[0]] = f[1]
		} else if block == "" && len(f) == 3 && f[0] == "require" {
			out[f[1]] = f[2]
		}
	}
	return out
}
